#!/usr/bin/env bash
# PreToolUse on Edit|Write: refuse edits that must never be made by hand.
#
#   - generated files: contracts/openapi.json, frontend/src/shared/api/generated/**,
#     backend/**/.sqlx/**
#   - owner-only files: backend/layers.toml
#   - files pinned by a signed contract tag: contracts/contracts.toml plus the
#     contract/<feature>/v<N> tags (skipped while no contract tag exists)
#   - setting the human-only VAK_REVIEWERS switch in .claude/settings*.json
#
# Denies with a PreToolUse permissionDecision and a reason Claude can act on.
# Prints nothing to allow. Always exits 0.
set -euo pipefail

HOOK_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=lib/common.sh
. "$HOOK_DIR/lib/common.sh"

deny() {
  printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":%s}}\n' \
    "$(json_string "$1")"
  exit 0
}

input=$(cat)
file=$(json_get "$input" tool_input.file_path)
[ -n "$file" ] || exit 0
cwd=$(json_get "$input" cwd)
locate_in_repo "$file" "$cwd" || exit 0
root=$REPO_ROOT
rel=$REPO_REL

# Generated and owner-only paths. Lower-cased, since macOS file systems ignore case.
lower=$(printf '%s' "$rel" | tr '[:upper:]' '[:lower:]')
case "$lower" in
  contracts/openapi.json)
    deny "contracts/openapi.json is generated from the Rust API (utoipa). Don't edit it by hand: change the backend, then run \`just openapi\` to regenerate it and the frontend client."
    ;;
  frontend/src/shared/api/generated/*)
    deny "$rel is generated by orval from contracts/openapi.json. Don't edit it by hand: change the API, then run \`just openapi\`."
    ;;
  backend/.sqlx/* | backend/*/.sqlx/*)
    deny "$rel is part of the sqlx offline query cache (.sqlx/), which is generated. Don't edit it by hand: run \`cargo sqlx prepare --workspace\` against a migrated database."
    ;;
  backend/layers.toml)
    deny "backend/layers.toml defines the layer rules and only the owner changes it. If a dependency must cross a layer, explain why in the PR description and leave this file alone."
    ;;
esac

# The reviewer switch is for humans only.
case "$lower" in
  .claude/settings.json | .claude/settings.local.json)
    content="$(json_get "$input" tool_input.content)$(json_get "$input" tool_input.new_string)"
    case "$content" in
      *VAK_REVIEWERS*)
        deny "VAK_REVIEWERS is a human-only switch for the Stop gate. Don't set it in settings files; ask the human to export it in their shell if they want reviewers off."
        ;;
    esac
    ;;
esac

# Files pinned by a signed contract tag.
tags=$(git -C "$root" for-each-ref --format='%(refname)' refs/tags/contract/ 2>/dev/null \
  | sed 's#^refs/tags/##' || true)
[ -n "$tags" ] || exit 0
if ! command -v python3 >/dev/null 2>&1; then
  echo "pre-edit-guard: python3 not found, contract tag check skipped" >&2
  exit 0
fi
# shellcheck disable=SC2086 # one argument per tag; tag names have no spaces
pinned=$(python3 -I "$HOOK_DIR/lib/contract_tags.py" "$root" "$rel" $tags 2>/dev/null || true)
if [ -n "$pinned" ]; then
  deny "$rel is pinned by the signed contract tag $pinned. Contract tests are never edited in place. To change the contract, bump the feature's version in contracts/contracts.toml first (the owner reviews and signs the new tag), then edit."
fi
exit 0
